export const FA = [{"n":1,"title":"Üç durak","notes":["c3","f3","c4"],"text":"Anahtarın iki noktası dördüncü çizgiyi sarar: bu çizgi Fa. İkinci aralık küçük Do, porte üstündeki kısa çizgi orta Do. Önce bu üçünü gözün kapalı bile bilir hale getir.","etudes":[{"id":"fa-01-0","title":"Uzun sesler","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-01-1","title":"Sıçrama","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-01-2","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-01-3","title":"Dörtlükler","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":2,"title":"Fa’nın komşuları","notes":["e3","f3","g3","c3","c4"],"text":"Fa çizgisinin hemen altındaki aralık Mi, üstündeki aralık Sol. Adı tek tek söylemek yerine “bir aşağı, bir yukarı” diye oku.","etudes":[{"id":"fa-02-0","title":"Adım adım","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-02-1","title":"Durağa dön","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-02-2","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-02-3","title":"Dörtlükte yürüyüş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":3,"title":"Do konumu","notes":["c3","d3","e3","f3","g3"],"text":"Beş parmak bu beş notanın üstünde: 5 Do’da, 1 Sol’da. Parmağı değil yönü oku: yukarı, aşağı, aynı.","etudes":[{"id":"fa-03-0","title":"Basamaklar","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-03-1","title":"Çıkış ve iniş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-03-2","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-03-3","title":"Atlamalı","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":4,"title":"Sol konumu","notes":["g2","a2","b2","c3","d3"],"text":"En alt çizgi kalın Sol. El bir konum aşağı iniyor: 5 Sol’da, 1 Re’de. Porte altına doğru okuma burada başlar.","etudes":[{"id":"fa-04-0","title":"Alt çizgiden","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-04-1","title":"Dörtlükler","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-04-2","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-04-3","title":"İki konum","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":5,"title":"Beş çizgi","notes":["g2","b2","d3","f3","a3"],"text":"Çizgiler alttan yukarı: Sol, Si, Re, Fa, La. Çizgiden çizgiye gitmek üçlü atlamadır; gözün arayı saymasın, biçimi görsün.","etudes":[{"id":"fa-05-0","title":"Çizgi merdiveni","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-05-1","title":"Atlayarak","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-05-2","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-05-3","title":"Karışık","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":6,"title":"Dört aralık","notes":["a2","c3","e3","g3"],"text":"Aralıklar alttan yukarı: La, Do, Mi, Sol. Çizgileri biliyorsan aralıklar onların tam arasındadır.","etudes":[{"id":"fa-06-0","title":"Aralık merdiveni","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-06-1","title":"Atlayarak","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-06-2","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-06-3","title":"Çizgi ile aralık","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":7,"title":"Bütün porte","notes":["g2","a2","b2","c3","d3","e3","f3","g3","a3","c4"],"text":"Artık porte üzerindeki her nota. Dörtlü ve beşli atlamalarda gözün durak notaya tutunsun: Sol, Do, Fa.","etudes":[{"id":"fa-07-0","title":"Dörtlü, beşli","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-07-1","title":"Ezgi: Do majör","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-07-2","title":"Ezgi: la minör","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-07-3","title":"Sekizlikli","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":8,"title":"Alt ek çizgiler","notes":["c2","d2","e2","f2","g2","a2","b2","c3"],"text":"Kalın Sol’un altı: aralıkta Fa, birinci ek çizgide Mi, sonra Re ve iki ek çizgide kalın Do. Basların yaşadığı yer burası.","etudes":[{"id":"fa-08-0","title":"Aşağı iniş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-08-1","title":"Durak: kalın Do","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-08-2","title":"Dörtlükler","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-08-3","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":9,"title":"Üst ek çizgiler","notes":["a3","b3","c4","d4","e4","f3","g3"],"text":"Orta Do’nun üstü: Re aralıkta, Mi ek çizgide. Sol el yüksek bölgede, sağ el sol anahtarının alt kısmıyla buluşur.","etudes":[{"id":"fa-09-0","title":"Yukarı çıkış","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-09-1","title":"Durak: orta Do","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-09-2","title":"Dörtlükler","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-09-3","title":"Üç vuruş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":10,"title":"Tondaki sesler","notes":["bb2","c#3","f#3"],"text":"Anahtarın yanındaki işaret parça boyunca geçerlidir. Sol majörde her Fa diyez, Fa majörde her Si bemol. Bir işaret görünce parçanın tonunu söyle, sonra başla.","etudes":[{"id":"fa-10-0","title":"Sol majör","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-10-1","title":"Fa majör","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-10-2","title":"Re majör","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-10-3","title":"re minör","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":11,"title":"Ritim","notes":["g2","a2","b2","c3","d3","e3","f3","g3","a3","c4"],"text":"Notayı artık biliyorsun; şimdi sürelerle birlikte oku. Sekizlik ve noktalı değerleri önce sayarak çal.","etudes":[{"id":"fa-11-0","title":"Noktalı dörtlük","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-11-1","title":"Üç sekiz","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-11-2","title":"Sus ve giriş","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-11-3","title":"On altılık","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]},{"n":12,"title":"Çift ses ve akor","notes":["c3","e3","g3","f3","a3","d3","g2","b2","c4"],"text":"Sol elin akorlarını üstten değil dipten oku. En alttaki nota kök mü, üçlü mü? Sonra üstündeki aralıkları gör.","etudes":[{"id":"fa-12-0","title":"Beşli ve üçlü","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-12-1","title":"Üç ses","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-12-2","title":"Vals eşliği","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"},{"id":"fa-12-3","title":"Kırık akor","bars":8,"tempo":66,"sections":[[0,8]],"kind":"fa"}]}];
